insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('ea8f9a66-f5a9-489f-a9d7-6a16a38d944e', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', null, 'topic'::public.curated_course_node_type, 'Foundations, History, Values, and Mutual Aid', 'Establishes social group work as a distinct, values-based practice in which purposeful group processes and member-to-member help advance individual and collective goals.', 0),
  ('1ba6efba-1712-482b-a411-c78b544d27c9', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'ea8f9a66-f5a9-489f-a9d7-6a16a38d944e', 'subtopic'::public.curated_course_node_type, 'Origins and scope of social group work', 'History helps students recognize group work as more than an efficient way to serve several individuals at once.', 0),
  ('19400454-55d5-4b9b-9892-46279d8ad9fe', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '1ba6efba-1712-482b-a411-c78b544d27c9', 'concept'::public.curated_course_node_type, 'Settlement-house, recreation, mutual-aid, clinical, and community traditions', null, 0),
  ('2b63819c-464f-4505-a3a5-4d1838a78098', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '1ba6efba-1712-482b-a411-c78b544d27c9', 'concept'::public.curated_course_node_type, 'Treatment and task-group lineages', null, 1),
  ('5306f18d-11fb-4630-ae4e-208f6643bb11', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '1ba6efba-1712-482b-a411-c78b544d27c9', 'concept'::public.curated_course_node_type, 'Group work across health, education, child welfare, justice, and community settings', null, 2),
  ('8faa261b-32e7-4b12-91a1-573c3141482f', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '1ba6efba-1712-482b-a411-c78b544d27c9', 'concept'::public.curated_course_node_type, 'Contemporary global and interdisciplinary practice', null, 3),
  ('baa8deec-59ad-4056-b2e6-45db8fb353a9', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'ea8f9a66-f5a9-489f-a9d7-6a16a38d944e', 'subtopic'::public.curated_course_node_type, 'Social-work values and perspectives', 'Professional values shape how power, dignity, autonomy, relationships, and collective responsibility are enacted in a group.', 1),
  ('bc37a969-cf41-45af-9157-1d6e917c3b78', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'baa8deec-59ad-4056-b2e6-45db8fb353a9', 'concept'::public.curated_course_node_type, 'Dignity and worth, self-determination, service, and integrity', null, 0),
  ('fef3fb62-3082-4855-8ebd-6bb39783f2cb', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'baa8deec-59ad-4056-b2e6-45db8fb353a9', 'concept'::public.curated_course_node_type, 'Person-in-environment and ecological perspectives', null, 1),
  ('96521be8-aa78-439f-b397-d1ccfc93035f', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'baa8deec-59ad-4056-b2e6-45db8fb353a9', 'concept'::public.curated_course_node_type, 'Strengths, empowerment, and recovery orientations', null, 2),
  ('72cb3548-a30a-4413-b7eb-f0c7678b1725', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'baa8deec-59ad-4056-b2e6-45db8fb353a9', 'concept'::public.curated_course_node_type, 'Human rights and social, racial, economic, and environmental justice', null, 3),
  ('237f7012-4067-4f68-8bae-b960e9fcdada', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'ea8f9a66-f5a9-489f-a9d7-6a16a38d944e', 'subtopic'::public.curated_course_node_type, 'Mutual aid as a distinguishing process', 'The facilitator''s goal is not to become the sole helper but to develop members'' capacity to help one another.', 2),
  ('3b5dbde0-4c9c-42b1-846a-dcc3a9b1f158', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '237f7012-4067-4f68-8bae-b960e9fcdada', 'concept'::public.curated_course_node_type, 'Sharing information and common experience', null, 0),
