  ('3bb6a1d9-d8cc-4f30-99c3-c8e0f571de76', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '237f7012-4067-4f68-8bae-b960e9fcdada', 'concept'::public.curated_course_node_type, 'Member leadership, reciprocity, and social action', null, 3),
  ('ab167478-9277-418a-ae1a-0c967c87cd68', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', null, 'topic'::public.curated_course_node_type, 'Group Types, Purposes, and Theoretical Frameworks', 'Differentiates treatment, support, psychoeducational, task, self-help, and social-action groups and links their purposes to appropriate theories and methods.', 1),
  ('9ce750a0-6461-4854-83f1-c7ac892e662d', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'ab167478-9277-418a-ae1a-0c967c87cd68', 'subtopic'::public.curated_course_node_type, 'Purposes and group formats', 'Clear classification prevents a mismatch between what a group promises and how it is led.', 0),
  ('0c8a8c9a-3434-4431-9e61-e18f4e2250e0', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '9ce750a0-6461-4854-83f1-c7ac892e662d', 'concept'::public.curated_course_node_type, 'Support, psychoeducational, treatment, skills, and socialization groups', null, 0),
  ('3391b0c6-a903-4bce-8ecc-38a55286af69', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '9ce750a0-6461-4854-83f1-c7ac892e662d', 'concept'::public.curated_course_node_type, 'Self-help and peer-led groups', null, 1),
  ('e71a7f85-7480-41b1-bb42-731f3850bc80', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '9ce750a0-6461-4854-83f1-c7ac892e662d', 'concept'::public.curated_course_node_type, 'Task groups, teams, committees, and boards', null, 2),
  ('40daa917-42f6-4b4e-8ef9-58ad7c3d34a0', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '9ce750a0-6461-4854-83f1-c7ac892e662d', 'concept'::public.curated_course_node_type, 'Community-action, advocacy, and coalition groups', null, 3),
