  ('dbd94cae-4768-43a9-9248-982615d1673b', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'a9082b56-47aa-43f7-b05a-09869ff7e4c3', 'concept'::public.curated_course_node_type, 'Systems and ecological theories', null, 0),
