  ('480e7258-f0d0-48f6-bdb9-abbfd917ed17', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'a9082b56-47aa-43f7-b05a-09869ff7e4c3', 'concept'::public.curated_course_node_type, 'Learning, cognitive-behavioral, and social-learning approaches', null, 2),
  ('2e030abf-e6ce-48ba-bb95-4c6ae6718a2e', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'a9082b56-47aa-43f7-b05a-09869ff7e4c3', 'concept'::public.curated_course_node_type, 'Strengths, empowerment, feminist, critical, and mutual-aid perspectives', null, 3),
  ('b9e9f105-818e-4ab5-99eb-57e2991d948e', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'ab167478-9277-418a-ae1a-0c967c87cd68', 'subtopic'::public.curated_course_node_type, 'Theory-to-method fit', 'Students learn to justify why a particular structure and intervention match the group''s purpose, setting, and members.', 2),
  ('85d07f06-f760-4675-86e9-6a6553b977a3', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'b9e9f105-818e-4ab5-99eb-57e2991d948e', 'concept'::public.curated_course_node_type, 'Open versus closed groups', null, 0),
  ('c26f7a59-2e60-41ce-af84-d45035ce26c5', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'b9e9f105-818e-4ab5-99eb-57e2991d948e', 'concept'::public.curated_course_node_type, 'Time-limited versus ongoing groups', null, 1),
  ('343e0987-0aca-47ff-9ca3-10caab5364ab', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'b9e9f105-818e-4ab5-99eb-57e2991d948e', 'concept'::public.curated_course_node_type, 'Homogeneous versus heterogeneous composition', null, 2),
  ('85f6bbf9-2819-4484-bbdc-e343b50f5151', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'b9e9f105-818e-4ab5-99eb-57e2991d948e', 'concept'::public.curated_course_node_type, 'Structured versus process-oriented sessions', null, 3),
  ('9850bf86-c4ed-410d-a26f-aba61ff5ec79', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', null, 'topic'::public.curated_course_node_type, 'Planning, Agency Context, and Group Proposal Development', 'Turns an identified need into a feasible, ethical group design aligned with community priorities, agency capacity, evidence, and resources.', 2),
  ('82d61606-4107-4916-84e2-488aa46c9103', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '9850bf86-c4ed-410d-a26f-aba61ff5ec79', 'subtopic'::public.curated_course_node_type, 'Needs and stakeholder assessment', 'A useful group begins with a real need defined with—not merely for—the people most affected.', 0),
  ('bd6a8f1f-48a7-4339-b414-1c88467fbc97', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '82d61606-4107-4916-84e2-488aa46c9103', 'concept'::public.curated_course_node_type, 'Community and agency data', null, 0),
