  ('4a163cfc-b364-42a7-a283-b15b60590067', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '82d61606-4107-4916-84e2-488aa46c9103', 'concept'::public.curated_course_node_type, 'Existing services, gaps, and referral pathways', null, 2),
