  ('3853f620-6f4c-49bc-8ff4-ddf917f0d837', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '9850bf86-c4ed-410d-a26f-aba61ff5ec79', 'subtopic'::public.curated_course_node_type, 'Purpose, goals, and theory of change', 'A precise purpose aligns membership, activities, staffing, and evaluation.', 1),
  ('0e386e6c-6879-448c-be49-80c1d3017536', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '3853f620-6f4c-49bc-8ff4-ddf917f0d837', 'concept'::public.curated_course_node_type, 'Purpose statement and target population', null, 0);
