  ('9147c055-d56b-43d4-99ae-c35d31b4478e', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', null, 'topic'::public.curated_course_node_type, 'Recruitment, Screening, Composition, and Informed Consent', 'Prepares social workers to build groups whose membership, access, expectations, and safeguards support both inclusion and purposeful work.', 3),
  ('6bfe5773-bdfc-46c7-9c78-2bbd7c9b3392', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '9147c055-d56b-43d4-99ae-c35d31b4478e', 'subtopic'::public.curated_course_node_type, 'Accessible recruitment', 'Recruitment should reach intended members without coercion, stigma, or avoidable barriers.', 0),
