  ('35315a59-5ddc-4d73-9aab-37fb01da4981', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '7176ea46-91de-40b9-b8d7-8b3ee95710c5', 'concept'::public.curated_course_node_type, 'Technology, recording, emergencies, and complaint procedures', null, 3),
  ('555d56ca-eed2-43e6-b3df-7e2419a740c3', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', null, 'topic'::public.curated_course_node_type, 'Group Dynamics and the Group as a Social System', 'Develops the ability to observe and influence norms, roles, status, cohesion, communication, power, subgroups, and mutual aid without reducing the group to individual cases.', 4),
  ('1078468a-469c-4acf-ba20-ea10c5c54213', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '555d56ca-eed2-43e6-b3df-7e2419a740c3', 'subtopic'::public.curated_course_node_type, 'Norms, roles, status, and power', 'These structures organize participation and can either reproduce inequity or support shared influence.', 0),
  ('192204f5-b152-4304-8734-ef3a2e51f9c1', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '1078468a-469c-4acf-ba20-ea10c5c54213', 'concept'::public.curated_course_node_type, 'Explicit and implicit norms', null, 0),
  ('fe37bb72-1418-4f40-b4d4-84810a3b8bfa', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '1078468a-469c-4acf-ba20-ea10c5c54213', 'concept'::public.curated_course_node_type, 'Task, maintenance, and individual roles', null, 1),
  ('0ca796bb-970b-4465-9b07-1adcdfff2c73', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '1078468a-469c-4acf-ba20-ea10c5c54213', 'concept'::public.curated_course_node_type, 'Status hierarchies and informal leadership', null, 2),
  ('6a1a1e9d-f4e7-4730-bc77-7c8b1ae0c952', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '1078468a-469c-4acf-ba20-ea10c5c54213', 'concept'::public.curated_course_node_type, 'Power, privilege, authority, and participation', null, 3),
  ('ffc5f8a3-c27d-450d-a82f-fab1ccbf88ae', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '555d56ca-eed2-43e6-b3df-7e2419a740c3', 'subtopic'::public.curated_course_node_type, 'Communication and cohesion', 'Patterns of speaking, listening, affiliation, and avoidance reveal how safe and workable the group feels.', 1),
  ('eef9088c-4328-4459-8293-8674316866d4', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'ffc5f8a3-c27d-450d-a82f-fab1ccbf88ae', 'concept'::public.curated_course_node_type, 'Interaction patterns and communication networks', null, 0),
  ('ad524fd1-81f5-47de-8515-fe96ca3ce567', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'ffc5f8a3-c27d-450d-a82f-fab1ccbf88ae', 'concept'::public.curated_course_node_type, 'Cohesion, belonging, and attendance', null, 1),
  ('b9d203d8-04ea-4143-8930-cc465bdaf37c', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'ffc5f8a3-c27d-450d-a82f-fab1ccbf88ae', 'concept'::public.curated_course_node_type, 'Subgroups, alliances, and boundaries', null, 2),
  ('7a1080b9-ca9c-41b6-be46-fa303b18cd14', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'ffc5f8a3-c27d-450d-a82f-fab1ccbf88ae', 'concept'::public.curated_course_node_type, 'Trust, psychological safety, and group climate', null, 3),
  ('3a7737d4-593c-4888-8b1f-662628ea9b75', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '555d56ca-eed2-43e6-b3df-7e2419a740c3', 'subtopic'::public.curated_course_node_type, 'Observation and assessment', 'Process observation helps the worker intervene in the group-as-a-whole rather than respond only to the loudest member.', 2),
  ('5cd585d8-8414-4c60-94d9-e27967a720e5', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '3a7737d4-593c-4888-8b1f-662628ea9b75', 'concept'::public.curated_course_node_type, 'Content versus process', null, 0),
  ('4a1382e9-d56d-4e04-948b-b29f5e1d24f7', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '3a7737d4-593c-4888-8b1f-662628ea9b75', 'concept'::public.curated_course_node_type, 'Here-and-now data', null, 1),
  ('fc2b2a72-1a26-4d9b-989b-3f1513db3ef8', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '3a7737d4-593c-4888-8b1f-662628ea9b75', 'concept'::public.curated_course_node_type, 'Sociograms and interaction maps', null, 2),
  ('fbb5f28d-499e-4ae5-9066-64ff28c55125', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '3a7737d4-593c-4888-8b1f-662628ea9b75', 'concept'::public.curated_course_node_type, 'Hypotheses, member feedback, and bias checking', null, 3);
