  ('21edf6d2-6f75-4652-b1dd-8ae1b48ae8a2', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '9b6a13c4-36a8-4006-86f1-3af47d671877', 'concept'::public.curated_course_node_type, 'Planning and preparation', null, 0),
