  ('9098acec-36bd-453c-93d5-b8e447637990', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '0ef85c70-3cd0-4dee-bada-e06d73a6dc55', 'concept'::public.curated_course_node_type, 'Mutual aid and productive work', null, 2),
  ('a95914f1-7a17-4093-b3c8-efd0996882f5', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '0ef85c70-3cd0-4dee-bada-e06d73a6dc55', 'concept'::public.curated_course_node_type, 'Goal review, practice, and generalization', null, 3),
  ('86b74f8f-a0d4-4ffa-bdb5-1cf0d47ba204', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'd57de825-95d3-4534-a362-b36ee9f81338', 'subtopic'::public.curated_course_node_type, 'Nonlinear development', 'Groups may regress, accelerate, or revisit earlier tasks after absences, crises, membership changes, or contextual events.', 2),
