  ('11cdcecf-55c4-4e09-b92a-633f0fdd1d90', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '86b74f8f-a0d4-4ffa-bdb5-1cf0d47ba204', 'concept'::public.curated_course_node_type, 'Recontracting after disruption', null, 3),
  ('55868527-a2c2-4b56-a719-4024f9fc2c80', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', null, 'topic'::public.curated_course_node_type, 'Facilitation Skills, Communication, and Use of Activities', 'Builds observable leadership skills for creating safety, deepening participation, supporting mutual aid, focusing work, and translating discussion into action.', 6),
  ('ba3c1113-963f-49af-b5e0-7d69d76e719a', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '55868527-a2c2-4b56-a719-4024f9fc2c80', 'subtopic'::public.curated_course_node_type, 'Core communication skills', 'Micro-skills help members feel understood while keeping the group connected to purpose.', 0),
  ('50f5590a-c43c-4d94-8308-fe6b9118d2dc', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'ba3c1113-963f-49af-b5e0-7d69d76e719a', 'concept'::public.curated_course_node_type, 'Attending, empathy, and active listening', null, 0),
