  ('a5952cec-f87f-474b-8f15-9e4f12782b19', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'ba3c1113-963f-49af-b5e0-7d69d76e719a', 'concept'::public.curated_course_node_type, 'Clarifying, paraphrasing, and summarizing', null, 2),
  ('99bf7c1e-e19d-4aee-af64-4e21a9647c17', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'ba3c1113-963f-49af-b5e0-7d69d76e719a', 'concept'::public.curated_course_node_type, 'Immediacy, feedback, and respectful challenge', null, 3),
  ('d4be19ac-b099-4a65-b05c-2e683a9fa6c2', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '55868527-a2c2-4b56-a719-4024f9fc2c80', 'subtopic'::public.curated_course_node_type, 'Group-centered interventions', 'Effective leaders connect members to one another instead of serially conducting individual sessions in public.', 1),
  ('794badc2-62cf-45bc-84d7-8a70c578bb44', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'd4be19ac-b099-4a65-b05c-2e683a9fa6c2', 'concept'::public.curated_course_node_type, 'Linking common themes and differences', null, 0),
