  ('f5447043-50d6-4cb7-a1c9-dfdb928be226', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '834724c0-97eb-4f62-89e6-8afa727b32a9', 'concept'::public.curated_course_node_type, 'Framing, opt-out choices, debriefing, and transfer', null, 3),
  ('86a47691-69b8-4d53-8e34-0d363efcbe23', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', null, 'topic'::public.curated_course_node_type, 'Co-Leadership, Teamwork, Supervision, and Professional Use of Self', 'Uses co-facilitation, reflection, feedback, and supervision to strengthen judgment, manage parallel process, and sustain accountable practice.', 7),
