  ('bde7bc13-d8f5-46f5-b65c-6abd53960d55', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '53ea78a9-ec2d-494a-8958-8a83ef13590b', 'concept'::public.curated_course_node_type, 'Role division and complementary strengths', null, 0),
