  ('ecab6031-a298-41cf-8500-061429b72f00', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '53ea78a9-ec2d-494a-8958-8a83ef13590b', 'concept'::public.curated_course_node_type, 'Disagreement, competition, and repair', null, 2),
