  ('4edc4ade-9b07-4480-bd7e-1a13e3375e1f', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', null, 'topic'::public.curated_course_node_type, 'Ethics, Law, Confidentiality, Boundaries, and Safety', 'Applies social-work ethics and local law to the distinctive risks of group consent, member-to-member privacy, records, mandated action, dual relationships, and technology.', 9),
  ('ef259158-1927-4787-b928-012dff6bb49e', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '4edc4ade-9b07-4480-bd7e-1a13e3375e1f', 'subtopic'::public.curated_course_node_type, 'Group-specific ethical practice', 'Group work intensifies consent, privacy, and power questions because members affect one another beyond the facilitator''s control.', 0),
