  ('38b3ee38-94a4-4275-b46c-c5e77cf3b532', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', null, 'topic'::public.curated_course_node_type, 'Task Groups, Teams, Coalitions, and Community-Action Groups', 'Extends group-work competence beyond treatment to committees, interdisciplinary teams, organizational change, advocacy, and collective action.', 12),
