  ('6ed467df-88bf-4cca-a067-577508efe055', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'daba2cfb-6fb1-4c88-a7fc-ee907e819031', 'concept'::public.curated_course_node_type, 'Charters, agendas, roles, and timelines', null, 0),
