  ('dc112049-9707-45bb-89b5-d6a46ee80564', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', 'daba2cfb-6fb1-4c88-a7fc-ee907e819031', 'concept'::public.curated_course_node_type, 'Consensus, voting, delegation, and accountability', null, 2),
