  ('609701fb-1ade-416a-9d03-fd3a929e7bc9', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', null, 'topic'::public.curated_course_node_type, 'Documentation, Measurement, and Practice Evaluation', 'Develops ethical records and feasible evaluation plans that connect group purpose, process, participation, outcomes, equity, and continuous improvement.', 13),
