insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('5eec1fb4-3d58-4cd7-9b45-277bec014e8f', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', null, 'topic'::public.curated_course_node_type, 'Ending, Transition, Follow-Up, and Integrative Practice', 'Treats termination as a planned phase for consolidating learning, acknowledging loss, evaluating outcomes, supporting next steps, and integrating professional competence.', 15),
