  ('67c50533-296e-4760-adc3-cf86076ebe83', 'f7a8b9c0-2d3e-4f57-8a67-7b8c9d0e1f77', '8374d450-57bc-4f84-9b88-4fc270f8127b', 'concept'::public.curated_course_node_type, 'Session plan linked to purpose and phase', null, 0),
