update public.learning_paths
set
  title = 'Social Work Practice with Groups',
  goal = 'Social Work Practice with Groups',
  summary = 'A Year 3 core practice course preparing BSW students to plan, form, facilitate, evaluate, and end treatment and task groups across social-service, health, educational, organizational, and community settings. The course emphasizes mutual aid, ethical and anti-oppressive practice, evidence-informed intervention, group-as-a-whole observation, supervised skills rehearsal, and reflective use of self.',
  data = $swgrjson${"slug": "social-work-practice-with-groups", "title": "Social Work Practice with Groups", "description": "A Year 3 core practice course preparing BSW students to plan, form, facilitate, evaluate, and end treatment and task groups across social-service, health, educational, organizational, and community settings. The course emphasizes mutual aid, ethical and anti-oppressive practice, evidence-informed intervention, group-as-a-whole observation, supervised skills rehearsal, and reflective use of self.", "topics": [{"id": "ea8f9a66-f5a9-489f-a9d7-6a16a38d944e", "type": "topic", "title": "Foundations, History, Values, and Mutual Aid", "description": "Establishes social group work as a distinct, values-based practice in which purposeful group processes and member-to-member help advance individual and collective goals.", "children": [{"id": "1ba6efba-1712-482b-a411-c78b544d27c9", "type": "subtopic", "title": "Origins and scope of social group work", "children": [{"id": "19400454-55d5-4b9b-9892-46279d8ad9fe", "type": "concept", "title": "Settlement-house, recreation, mutual-aid, clinical, and community traditions"}, {"id": "2b63819c-464f-4505-a3a5-4d1838a78098", "type": "concept", "title": "Treatment and task-group lineages"}, {"id": "5306f18d-11fb-4630-ae4e-208f6643bb11", "type": "concept", "title": "Group work across health, education, child welfare, justice, and community settings"}, {"id": "8faa261b-32e7-4b12-91a1-573c3141482f", "type": "concept", "title": "Contemporary global and interdisciplinary practice"}], "description": "History helps students recognize group work as more than an efficient way to serve several individuals at once."}, {"id": "baa8deec-59ad-4056-b2e6-45db8fb353a9", "type": "subtopic", "title": "Social-work values and perspectives", "children": [{"id": "bc37a969-cf41-45af-9157-1d6e917c3b78", "type": "concept", "title": "Dignity and worth, self-determination, service, and integrity"}, {"id": "fef3fb62-3082-4855-8ebd-6bb39783f2cb", "type": "concept", "title": "Person-in-environment and ecological perspectives"}, {"id": "96521be8-aa78-439f-b397-d1ccfc93035f", "type": "concept", "title": "Strengths, empowerment, and recovery orientations"}, {"id": "72cb3548-a30a-4413-b7eb-f0c7678b1725", "type": "concept", "title": "Human rights and social, racial, economic, and environmental justice"}], "description": "Professional values shape how power, dignity, autonomy, relationships, and collective responsibility are enacted in a group."}, {"id": "237f7012-4067-4f68-8bae-b960e9fcdada", "type": "subtopic", "title": "Mutual aid as a distinguishing process", "children": [{"id": "3b5dbde0-4c9c-42b1-846a-dcc3a9b1f158", "type": "concept", "title": "Sharing information and common experience"}, {"id": "f1ca496f-5e5b-45ec-b5b0-551cdcef117e", "type": "concept", "title": "Support, challenge, validation, and universality"}, {"id": "98f361cb-6161-40b2-bfe3-7dac12dadb5c", "type": "concept", "title": "Collective problem solving and rehearsal"}, {"id": "3bb6a1d9-d8cc-4f30-99c3-c8e0f571de76", "type": "concept", "title": "Member leadership, reciprocity, and social action"}], "description": "The facilitator's goal is not to become the sole helper but to develop members' capacity to help one another."}]}, {"id": "ab167478-9277-418a-ae1a-0c967c87cd68", "type": "topic", "title": "Group Types, Purposes, and Theoretical Frameworks", "description": "Differentiates treatment, support, psychoeducational, task, self-help, and social-action groups and links their purposes to appropriate theories and methods.", "children": [{"id": "9ce750a0-6461-4854-83f1-c7ac892e662d", "type": "subtopic", "title": "Purposes and group formats", "children": [{"id": "0c8a8c9a-3434-4431-9e61-e18f4e2250e0", "type": "concept", "title": "Support, psychoeducational, treatment, skills, and socialization groups"}, {"id": "3391b0c6-a903-4bce-8ecc-38a55286af69", "type": "concept", "title": "Self-help and peer-led groups"}, {"id": "e71a7f85-7480-41b1-bb42-731f3850bc80", "type": "concept", "title": "Task groups, teams, committees, and boards"}, {"id": "40daa917-42f6-4b4e-8ef9-58ad7c3d34a0", "type": "concept", "title": "Community-action, advocacy, and coalition groups"}], "description": "Clear classification prevents a mismatch between what a group promises and how it is led."}, {"id": "a9082b56-47aa-43f7-b05a-09869ff7e4c3", "type": "subtopic", "title": "Theory for understanding process", "children": [{"id": "dbd94cae-4768-43a9-9248-982615d1673b", "type": "concept", "title": "Systems and ecological theories"}, {"id": "a5932d19-8ca9-43f7-9111-62a5998292ea", "type": "concept", "title": "Psychodynamic and interpersonal perspectives"}, {"id": "480e7258-f0d0-48f6-bdb9-abbfd917ed17", "type": "concept", "title": "Learning, cognitive-behavioral, and social-learning approaches"}, {"id": "2e030abf-e6ce-48ba-bb95-4c6ae6718a2e", "type": "concept", "title": "Strengths, empowerment, feminist, critical, and mutual-aid perspectives"}], "description": "Theories are lenses for noticing patterns and selecting interventions, not labels applied mechanically."}, {"id": "b9e9f105-818e-4ab5-99eb-57e2991d948e", "type": "subtopic", "title": "Theory-to-method fit", "children": [{"id": "85d07f06-f760-4675-86e9-6a6553b977a3", "type": "concept", "title": "Open versus closed groups"}, {"id": "c26f7a59-2e60-41ce-af84-d45035ce26c5", "type": "concept", "title": "Time-limited versus ongoing groups"}, {"id": "343e0987-0aca-47ff-9ca3-10caab5364ab", "type": "concept", "title": "Homogeneous versus heterogeneous composition"}, {"id": "85f6bbf9-2819-4484-bbdc-e343b50f5151", "type": "concept", "title": "Structured versus process-oriented sessions"}], "description": "Students learn to justify why a particular structure and intervention match the group's purpose, setting, and members."}]}, {"id": "9850bf86-c4ed-410d-a26f-aba61ff5ec79", "type": "topic", "title": "Planning, Agency Context, and Group Proposal Development", "description": "Turns an identified need into a feasible, ethical group design aligned with community priorities, agency capacity, evidence, and resources.", "children": [{"id": "82d61606-4107-4916-84e2-488aa46c9103", "type": "subtopic", "title": "Needs and stakeholder assessment", "children": [{"id": "bd6a8f1f-48a7-4339-b414-1c88467fbc97", "type": "concept", "title": "Community and agency data"}, {"id": "45099f22-6953-4ce2-ae39-c732674209e0", "type": "concept", "title": "Member and stakeholder consultation"}, {"id": "4a163cfc-b364-42a7-a283-b15b60590067", "type": "concept", "title": "Existing services, gaps, and referral pathways"}, {"id": "97b40fd6-2785-478b-890d-b0310ffcfd33", "type": "concept", "title": "Cultural and structural interpretations of need"}], "description": "A useful group begins with a real need defined with—not merely for—the people most affected."}, {"id": "3853f620-6f4c-49bc-8ff4-ddf917f0d837", "type": "subtopic", "title": "Purpose, goals, and theory of change", "children": [{"id": "0e386e6c-6879-448c-be49-80c1d3017536", "type": "concept", "title": "Purpose statement and target population"}, {"id": "46c6ab03-ef6d-4a3b-b3a3-a7802d438195", "type": "concept", "title": "SMART and member-generated goals"}, {"id": "0527f9a5-4734-45bc-b25f-cde59812b982", "type": "concept", "title": "Inputs, activities, outputs, and outcomes"}, {"id": "67d941b2-de81-4867-964c-d9f3630cf5fd", "type": "concept", "title": "Assumptions, external factors, and unintended effects"}], "description": "A precise purpose aligns membership, activities, staffing, and evaluation."}, {"id": "10156cdf-328d-49b3-bbd5-499ae12d14fc", "type": "subtopic", "title": "Feasibility and organizational support", "children": [{"id": "bb3e1f2a-608c-4351-974d-368315c2fcd8", "type": "concept", "title": "Agency mandate, policies, and supervision"}, {"id": "0bb62bb4-7889-40d1-8f32-cef5d411a875", "type": "concept", "title": "Budget, space, scheduling, staffing, and caseload"}, {"id": "9957a980-a5b6-4f5b-bad1-cb7062cbf217", "type": "concept", "title": "Referral and communication systems"}, {"id": "64b8b869-d123-412c-97bf-ddb3dcf37267", "type": "concept", "title": "Sustainability, stakeholder approval, and contingency planning"}], "description": "Even a sound intervention fails without authority, resources, access, and implementation support."}]}, {"id": "9147c055-d56b-43d4-99ae-c35d31b4478e", "type": "topic", "title": "Recruitment, Screening, Composition, and Informed Consent", "description": "Prepares social workers to build groups whose membership, access, expectations, and safeguards support both inclusion and purposeful work.", "children": [{"id": "6bfe5773-bdfc-46c7-9c78-2bbd7c9b3392", "type": "subtopic", "title": "Accessible recruitment", "children": [{"id": "1b4b5aa7-df57-4df2-8efc-3ab8ebc4a144", "type": "concept", "title": "Plain-language outreach and referral relationships"}, {"id": "34b7d56e-bc05-40a5-ae60-4a7c16781599", "type": "concept", "title": "Language access and disability accommodations"}, {"id": "cb6a33a0-2ba5-45ae-af3d-0ed98ffd5f4a", "type": "concept", "title": "Transportation, childcare, technology, and scheduling barriers"}, {"id": "860588fc-8e67-4c89-83ba-9ad94c9da4fd", "type": "concept", "title": "Voluntariness and power in mandated settings"}], "description": "Recruitment should reach intended members without coercion, stigma, or avoidable barriers."}, {"id": "d738b473-59dc-41f6-8c19-d28e08c2ec7a", "type": "subtopic", "title": "Screening and composition", "children": [{"id": "5b729622-1461-4470-8155-408f7d5c34f4", "type": "concept", "title": "Needs, goals, readiness, and expectations"}, {"id": "5111ea6c-1836-478b-aa48-2e182dcf6118", "type": "concept", "title": "Inclusion/exclusion criteria and reasonable accommodation"}, {"id": "1e75fb05-52ed-439e-aac1-279fd571651b", "type": "concept", "title": "Risk, interpersonal fit, and group readiness"}, {"id": "61c5a8ea-cd64-4b0e-b96c-7f366035279c", "type": "concept", "title": "Size, diversity, developmental level, and open/closed membership"}], "description": "Screening seeks fit and safety while avoiding discriminatory exclusion."}, {"id": "7176ea46-91de-40b9-b8d7-8b3ee95710c5", "type": "subtopic", "title": "Orientation and informed consent", "children": [{"id": "c2237803-bb5b-45f1-b2f6-c74b3a2dd43e", "type": "concept", "title": "Purpose, methods, benefits, risks, alternatives, and fees"}, {"id": "18b8e8f5-8747-482f-9753-5f5864876e4e", "type": "concept", "title": "Confidentiality and its member-to-member limits"}, {"id": "e5b34b41-eb55-49af-a635-f65af590475b", "type": "concept", "title": "Attendance, communication, records, and withdrawal"}, {"id": "35315a59-5ddc-4d73-9aab-37fb01da4981", "type": "concept", "title": "Technology, recording, emergencies, and complaint procedures"}], "description": "Pre-group preparation makes expectations visible and gives prospective members a meaningful choice."}]}, {"id": "555d56ca-eed2-43e6-b3df-7e2419a740c3", "type": "topic", "title": "Group Dynamics and the Group as a Social System", "description": "Develops the ability to observe and influence norms, roles, status, cohesion, communication, power, subgroups, and mutual aid without reducing the group to individual cases.", "children": [{"id": "1078468a-469c-4acf-ba20-ea10c5c54213", "type": "subtopic", "title": "Norms, roles, status, and power", "children": [{"id": "192204f5-b152-4304-8734-ef3a2e51f9c1", "type": "concept", "title": "Explicit and implicit norms"}, {"id": "fe37bb72-1418-4f40-b4d4-84810a3b8bfa", "type": "concept", "title": "Task, maintenance, and individual roles"}, {"id": "0ca796bb-970b-4465-9b07-1adcdfff2c73", "type": "concept", "title": "Status hierarchies and informal leadership"}, {"id": "6a1a1e9d-f4e7-4730-bc77-7c8b1ae0c952", "type": "concept", "title": "Power, privilege, authority, and participation"}], "description": "These structures organize participation and can either reproduce inequity or support shared influence."}, {"id": "ffc5f8a3-c27d-450d-a82f-fab1ccbf88ae", "type": "subtopic", "title": "Communication and cohesion", "children": [{"id": "eef9088c-4328-4459-8293-8674316866d4", "type": "concept", "title": "Interaction patterns and communication networks"}, {"id": "ad524fd1-81f5-47de-8515-fe96ca3ce567", "type": "concept", "title": "Cohesion, belonging, and attendance"}, {"id": "b9d203d8-04ea-4143-8930-cc465bdaf37c", "type": "concept", "title": "Subgroups, alliances, and boundaries"}, {"id": "7a1080b9-ca9c-41b6-be46-fa303b18cd14", "type": "concept", "title": "Trust, psychological safety, and group climate"}], "description": "Patterns of speaking, listening, affiliation, and avoidance reveal how safe and workable the group feels."}, {"id": "3a7737d4-593c-4888-8b1f-662628ea9b75", "type": "subtopic", "title": "Observation and assessment", "children": [{"id": "5cd585d8-8414-4c60-94d9-e27967a720e5", "type": "concept", "title": "Content versus process"}, {"id": "4a1382e9-d56d-4e04-948b-b29f5e1d24f7", "type": "concept", "title": "Here-and-now data"}, {"id": "fc2b2a72-1a26-4d9b-989b-3f1513db3ef8", "type": "concept", "title": "Sociograms and interaction maps"}, {"id": "fbb5f28d-499e-4ae5-9066-64ff28c55125", "type": "concept", "title": "Hypotheses, member feedback, and bias checking"}], "description": "Process observation helps the worker intervene in the group-as-a-whole rather than respond only to the loudest member."}]}, {"id": "d57de825-95d3-4534-a362-b36ee9f81338", "type": "topic", "title": "Stages of Group Development and Phase-Specific Practice", "description": "Links changing group needs across pre-affiliation, beginning, working, transition, and ending phases to deliberate worker tasks.", "children": [{"id": "9b6a13c4-36a8-4006-86f1-3af47d671877", "type": "subtopic", "title": "Pre-group and beginning phase", "children": [{"id": "21edf6d2-6f75-4652-b1dd-8ae1b48ae8a2", "type": "concept", "title": "Planning and preparation"}, {"id": "f36f0e82-efe6-4c2e-a30a-e4e8e06fc7b7", "type": "concept", "title": "Introductions and orientation"}, {"id": "5ca3f38d-8741-49b7-bfed-a074bebdade4", "type": "concept", "title": "Contracting and group agreements"}, {"id": "f9a2d5f0-acb4-4bd3-9f34-f32cbc4e9eda", "type": "concept", "title": "Early cohesion, goals, and participation"}], "description": "Early worker tasks create clarity, safety, connection, and realistic expectations."}, {"id": "0ef85c70-3cd0-4dee-bada-e06d73a6dc55", "type": "subtopic", "title": "Transition and working phases", "children": [{"id": "d7dd1f49-9c59-4a15-b795-16a5d7a30dc4", "type": "concept", "title": "Testing, ambivalence, and resistance"}, {"id": "84383a94-ee2f-4e35-a166-912afb76ba1d", "type": "concept", "title": "Conflict and norm renegotiation"}, {"id": "9098acec-36bd-453c-93d5-b8e447637990", "type": "concept", "title": "Mutual aid and productive work"}, {"id": "a95914f1-7a17-4093-b3c8-efd0996882f5", "type": "concept", "title": "Goal review, practice, and generalization"}], "description": "As trust and tension develop, leadership shifts toward deeper mutual work and member responsibility."}, {"id": "86b74f8f-a0d4-4ffa-bdb5-1cf0d47ba204", "type": "subtopic", "title": "Nonlinear development", "children": [{"id": "40f30d8f-b0e6-47e6-8801-a6162a817d9f", "type": "concept", "title": "Stage models as guides rather than rules"}, {"id": "58f8570c-13b5-4393-a75c-957f039da1f0", "type": "concept", "title": "Open-group cycles"}, {"id": "720da2e2-7119-4a9f-91ef-5f2d90678a56", "type": "concept", "title": "Impact of trauma and external events"}, {"id": "11cdcecf-55c4-4e09-b92a-633f0fdd1d90", "type": "concept", "title": "Recontracting after disruption"}], "description": "Groups may regress, accelerate, or revisit earlier tasks after absences, crises, membership changes, or contextual events."}]}, {"id": "55868527-a2c2-4b56-a719-4024f9fc2c80", "type": "topic", "title": "Facilitation Skills, Communication, and Use of Activities", "description": "Builds observable leadership skills for creating safety, deepening participation, supporting mutual aid, focusing work, and translating discussion into action.", "children": [{"id": "ba3c1113-963f-49af-b5e0-7d69d76e719a", "type": "subtopic", "title": "Core communication skills", "children": [{"id": "50f5590a-c43c-4d94-8308-fe6b9118d2dc", "type": "concept", "title": "Attending, empathy, and active listening"}, {"id": "c6c1165c-8abf-482f-82d3-46c407d28d6c", "type": "concept", "title": "Open and focused questions"}, {"id": "a5952cec-f87f-474b-8f15-9e4f12782b19", "type": "concept", "title": "Clarifying, paraphrasing, and summarizing"}, {"id": "99bf7c1e-e19d-4aee-af64-4e21a9647c17", "type": "concept", "title": "Immediacy, feedback, and respectful challenge"}], "description": "Micro-skills help members feel understood while keeping the group connected to purpose."}, {"id": "d4be19ac-b099-4a65-b05c-2e683a9fa6c2", "type": "subtopic", "title": "Group-centered interventions", "children": [{"id": "794badc2-62cf-45bc-84d7-8a70c578bb44", "type": "concept", "title": "Linking common themes and differences"}, {"id": "fbffece6-205a-465c-948a-e7433f40ba4c", "type": "concept", "title": "Inviting quieter voices and limiting monopolizing"}, {"id": "4b5d54f5-4567-46ea-a9f2-f5c277c96e11", "type": "concept", "title": "Universalizing without minimizing"}, {"id": "c73db80d-2ddf-4e2a-84d9-a50655c1f3db", "type": "concept", "title": "Supporting member-to-member feedback and help"}], "description": "Effective leaders connect members to one another instead of serially conducting individual sessions in public."}, {"id": "834724c0-97eb-4f62-89e6-8afa727b32a9", "type": "subtopic", "title": "Purposeful activities", "children": [{"id": "afbc3667-370c-4aeb-bcc8-533d622431ed", "type": "concept", "title": "Rounds, dyads, role plays, rehearsal, and problem solving"}, {"id": "8a436133-a27d-4cc2-b3b3-2b24a917c4bf", "type": "concept", "title": "Psychoeducation and skills practice"}, {"id": "dcc4a47a-adfd-496f-a3df-79c75b97d4bc", "type": "concept", "title": "Creative, embodied, and experiential methods"}, {"id": "f5447043-50d6-4cb7-a1c9-dfdb928be226", "type": "concept", "title": "Framing, opt-out choices, debriefing, and transfer"}], "description": "Exercises are useful only when their purpose, accessibility, pacing, and debrief are clear."}]}, {"id": "86a47691-69b8-4d53-8e34-0d363efcbe23", "type": "topic", "title": "Co-Leadership, Teamwork, Supervision, and Professional Use of Self", "description": "Uses co-facilitation, reflection, feedback, and supervision to strengthen judgment, manage parallel process, and sustain accountable practice.", "children": [{"id": "53ea78a9-ec2d-494a-8958-8a83ef13590b", "type": "subtopic", "title": "Co-leadership design", "children": [{"id": "bde7bc13-d8f5-46f5-b65c-6abd53960d55", "type": "concept", "title": "Role division and complementary strengths"}, {"id": "f255d963-2a73-4b11-aca7-9b0d18c31ae7", "type": "concept", "title": "Pre-briefs, in-session signals, and debriefs"}, {"id": "ecab6031-a298-41cf-8500-061429b72f00", "type": "concept", "title": "Disagreement, competition, and repair"}, {"id": "6fc017a3-a097-4ced-8745-307c74e5ede1", "type": "concept", "title": "Modelling collaboration and shared power"}], "description": "Co-leadership can expand observation and support but requires explicit agreements and shared accountability."}, {"id": "b9146be9-1da9-44a7-861b-5c88052819bb", "type": "subtopic", "title": "Professional use of self", "children": [{"id": "4cea1dd4-c1c5-4057-8ebc-70a48dc856e7", "type": "concept", "title": "Self-awareness and positionality"}, {"id": "c9ac0317-6d41-4e03-b1e3-1bf96a7de46b", "type": "concept", "title": "Emotional responses and countertransference awareness"}, {"id": "a161fdbc-29a8-4bd0-9900-3f2bf5f5291f", "type": "concept", "title": "Selective self-disclosure"}, {"id": "3e70df77-5551-46c9-b518-08006e9d1dad", "type": "concept", "title": "Boundaries, authenticity, and purposeful presence"}], "description": "Facilitators must notice how identity, emotion, authority, and personal history shape their interventions."}, {"id": "f9d31943-a68b-47b4-a66d-07a9f82c029a", "type": "subtopic", "title": "Supervision and reflective practice", "children": [{"id": "5b8676d5-56c8-406d-8473-73c7910cb594", "type": "concept", "title": "Agenda setting and case/process presentation"}, {"id": "9aa9caf6-114d-41f6-b15b-462a4de63fbe", "type": "concept", "title": "Use of recordings, transcripts, and process notes"}, {"id": "9afd9ab2-33e5-4506-bc52-be91c4311d19", "type": "concept", "title": "Feedback reception and deliberate practice"}, {"id": "8e60a511-3815-4c24-9e87-ed4b3dcc42f6", "type": "concept", "title": "Parallel process, impairment, and consultation thresholds"}], "description": "Supervision converts uncertainty and mistakes into safer, more competent practice."}]}, {"id": "afa50604-15bc-45d6-a5fa-7818e60d71f6", "type": "topic", "title": "Anti-Oppressive, Culturally Responsive, and Justice-Oriented Group Work", "description": "Centers power, identity, intersectionality, accessibility, and social justice in group purpose, membership, leadership, participation, and evaluation.", "children": [{"id": "4827b7d5-d594-4811-8739-c34432ac4b3b", "type": "subtopic", "title": "Identity, intersectionality, and context", "children": [{"id": "3690a4da-806b-4afa-99e9-d3fae2b9c69c", "type": "concept", "title": "Race, ethnicity, Indigeneity, culture, and migration"}, {"id": "30aaa97e-ec03-4bd5-bb98-94cfc4512f6f", "type": "concept", "title": "Gender, sexuality, class, religion, age, and family status"}, {"id": "3e9c8130-2d75-43df-a655-2c1c0e648dca", "type": "concept", "title": "Disability, neurodiversity, language, and health"}, {"id": "2703fb44-838f-4201-8743-6d77f4b6505d", "type": "concept", "title": "Intersectionality and within-group difference"}], "description": "Members bring multiple identities shaped by history, institutions, and unequal access to power."}, {"id": "bf436533-fa67-4b89-8e00-9804fbe19662", "type": "subtopic", "title": "Power-conscious facilitation", "children": [{"id": "84af7c76-714a-4d2a-8dd6-be1cbbc5f7eb", "type": "concept", "title": "Facilitator authority and positionality"}, {"id": "0e134c75-58c6-4f4c-8ce4-3682de903e90", "type": "concept", "title": "Microaggressions, bias, and stereotype threat"}, {"id": "3da8b065-20d3-4cbe-9857-1b97ffb78ea7", "type": "concept", "title": "Language justice and accessible participation"}, {"id": "9799c295-151d-439f-9d66-ed4bc3f5abb8", "type": "concept", "title": "Shared decision-making and member leadership"}], "description": "Inclusive practice requires attention to who defines the agenda, whose knowledge counts, and whose participation is constrained."}, {"id": "8f2f3ec2-162e-4448-afe4-5ef052430af5", "type": "subtopic", "title": "Justice, advocacy, and repair", "children": [{"id": "330334c5-2b2c-49c6-9c02-a76f12e23fcc", "type": "concept", "title": "Naming structural oppression"}, {"id": "4a88e853-50f7-4908-b379-3e4f3c680f2c", "type": "concept", "title": "Collective analysis and consciousness raising"}, {"id": "c1fb9f58-73a4-4ce1-a720-ac0be8aabfaa", "type": "concept", "title": "Advocacy and social action"}, {"id": "01c5fb34-be55-48a7-b593-e006addbfa52", "type": "concept", "title": "Accountability, apology, repair, and institutional change"}], "description": "Groups can address both personal impact and the conditions producing harm."}]}, {"id": "4edc4ade-9b07-4480-bd7e-1a13e3375e1f", "type": "topic", "title": "Ethics, Law, Confidentiality, Boundaries, and Safety", "description": "Applies social-work ethics and local law to the distinctive risks of group consent, member-to-member privacy, records, mandated action, dual relationships, and technology.", "children": [{"id": "ef259158-1927-4787-b928-012dff6bb49e", "type": "subtopic", "title": "Group-specific ethical practice", "children": [{"id": "db382078-3370-4dd8-9176-9ebe412eb748", "type": "concept", "title": "NASW Code of Ethics and IASWG Standards"}, {"id": "a8ca4a13-412b-452e-b39e-0ff06a134641", "type": "concept", "title": "Self-determination and informed consent"}, {"id": "a070fea1-6dab-4bd2-adc9-06b535068324", "type": "concept", "title": "Member-to-member confidentiality limits"}, {"id": "b8fa1006-1d33-4a1c-ae00-16a5fa7005a7", "type": "concept", "title": "Competence, conflicts of interest, and cultural humility"}], "description": "Group work intensifies consent, privacy, and power questions because members affect one another beyond the facilitator's control."}, {"id": "cb72cb36-6635-4197-b104-6dd4a6eeec18", "type": "subtopic", "title": "Boundaries and records", "children": [{"id": "675bb83f-2ebf-4d19-84f2-d0bd32e10327", "type": "concept", "title": "Dual and multiple relationships"}, {"id": "33f20eca-280a-4440-a128-748f70e00ace", "type": "concept", "title": "Contact outside group and social media"}, {"id": "5edd4930-c672-4520-9d44-f7ecf694a873", "type": "concept", "title": "Individual versus group records"}, {"id": "c2c357a2-0aff-4eeb-b57c-274bed626f92", "type": "concept", "title": "Subpoenas, releases, access, retention, and secure disposal"}], "description": "Clear policies protect members while preserving appropriate connection and continuity."}, {"id": "019cc74a-ded8-425d-b027-48b78e9ab278", "type": "subtopic", "title": "Risk, law, and ethical decisions", "children": [{"id": "02accea9-8360-4f46-9bf6-1b73db7e1f15", "type": "concept", "title": "Mandated reporting and duty-related obligations"}, {"id": "ce3a7403-1fe4-49c3-8591-b8aed6c178fa", "type": "concept", "title": "Suicide, violence, abuse, exploitation, and acute impairment"}, {"id": "fd8fd855-57b1-4656-8ae3-f1cb62f01f32", "type": "concept", "title": "Jurisdiction and agency policy"}, {"id": "678c1940-cd84-450c-aee2-76adefdd6c34", "type": "concept", "title": "Consultation, least-harm options, documentation, and follow-up"}], "description": "Students need a transparent process for situations where duties, rights, policy, and law conflict."}]}, {"id": "8f502a0d-07b5-4a82-9ba4-c2f8ef45cde8", "type": "topic", "title": "Conflict, Difficult Dynamics, Rupture, and Crisis Response", "description": "Equips students to assess and respond to silence, monopolizing, scapegoating, conflict, resistance, attrition, dysregulation, and acute safety concerns.", "children": [{"id": "108d7dad-d045-42d1-97c5-e0582eb2be38", "type": "subtopic", "title": "Common challenging patterns", "children": [{"id": "053718a2-f604-4f92-be54-a93c5cb2ab18", "type": "concept", "title": "Silence, lateness, absence, and withdrawal"}, {"id": "80b4fe87-7147-4ebe-b37c-4c6e9e2ba1d2", "type": "concept", "title": "Monopolizing, advice giving, and rescuing"}, {"id": "856cc184-5cfe-4b0c-8da8-2198faced4bd", "type": "concept", "title": "Scapegoating, subgroup conflict, and exclusion"}, {"id": "0b54fedf-1f0f-47a3-af37-28ba45dcfff6", "type": "concept", "title": "Hostility, boundary testing, and disruption"}], "description": "Difficult behavior is assessed as communication within a system, not simply as a defective member."}, {"id": "941f73a9-bace-4615-9456-cb1fdd010d48", "type": "subtopic", "title": "Conflict and rupture repair", "children": [{"id": "c93d5e3a-2794-4365-b83e-82af8f88b6d4", "type": "concept", "title": "De-escalation and affect regulation"}, {"id": "73512cb9-f0b8-4ef4-b806-a7c598632911", "type": "concept", "title": "Naming process without shaming"}, {"id": "64e90b44-7655-403f-b058-d4b0f164144e", "type": "concept", "title": "Perspective taking and conflict transformation"}, {"id": "5ccc1429-a5bd-42ca-ba30-dfe3334f4b2e", "type": "concept", "title": "Accountability, repair, and renewed agreements"}], "description": "Well-held conflict can clarify difference, strengthen norms, and restore trust."}, {"id": "dbd5fc1d-f408-4b94-906c-6274ee7eb796", "type": "subtopic", "title": "Crisis response", "children": [{"id": "95bba71b-d8e3-44d8-9e09-5c85716478eb", "type": "concept", "title": "Risk recognition and immediate stabilization"}, {"id": "aa24d411-3bab-4325-879c-86efb9d19397", "type": "concept", "title": "Co-leader roles and emergency protocols"}, {"id": "62a5987f-98dc-4625-b057-c41e95cf53f1", "type": "concept", "title": "Private follow-up and referral"}, {"id": "03d338ee-ca3c-400f-8727-05def434b0f4", "type": "concept", "title": "Group processing, documentation, consultation, and postvention"}], "description": "Facilitators must preserve group safety while responding proportionately to urgent individual or collective concerns."}]}, {"id": "6dc397df-e382-4202-a05b-1d9f2bae4dbb", "type": "topic", "title": "Evidence-Informed, Trauma-Responsive, and Population-Specific Interventions", "description": "Combines research evidence, practice wisdom, client preferences, cultural context, and trauma responsiveness when selecting structured group methods.", "children": [{"id": "454c63ad-2108-425d-a98e-30d80db91a32", "type": "subtopic", "title": "Evidence-informed decision-making", "children": [{"id": "73e029cf-431b-419a-88c2-ff8a8f872b50", "type": "concept", "title": "Formulating answerable practice questions"}, {"id": "f4b4d476-bbdb-45a4-825d-0242bb83b5f9", "type": "concept", "title": "Locating and appraising reviews, guidelines, and manuals"}, {"id": "03442b92-59dd-46b1-8a15-3fef71d331b8", "type": "concept", "title": "Effect size, applicability, feasibility, and harms"}, {"id": "34d801c7-bb29-413e-80d4-7057de88956a", "type": "concept", "title": "Adaptation with fidelity to core functions"}], "description": "Strong practice integrates research, professional judgment, member preferences, culture, and setting."}, {"id": "b56eefad-461a-4e94-878f-2235880867f3", "type": "subtopic", "title": "Trauma-responsive group work", "children": [{"id": "a60ab4d2-1dc7-4d4c-9a2f-a5ed64a4cc51", "type": "concept", "title": "Safety, trust, choice, collaboration, and empowerment"}, {"id": "4b93f0b6-f267-473a-a5e1-e3f3d4239421", "type": "concept", "title": "Predictability and transparent structure"}, {"id": "212ead32-8882-4e88-aa4b-86f4f6f6e485", "type": "concept", "title": "Grounding, pacing, and noncompulsory disclosure"}, {"id": "283e7e99-9477-4fad-8bf9-b226f1426fb7", "type": "concept", "title": "Avoiding retraumatization and responding to activation"}], "description": "Groups can support connection and agency but can also recreate coercion, exposure, and loss of control."}, {"id": "c0c6df1c-a16f-44c2-9730-9733502c08a7", "type": "subtopic", "title": "Population and setting adaptation", "children": [{"id": "182c5cc3-1d99-41e3-ae95-babf143b0a95", "type": "concept", "title": "Children, adolescents, adults, and older adults"}, {"id": "55cd2efc-f891-4794-a685-186e42a88b93", "type": "concept", "title": "Behavioral health, grief, health, schools, justice, and child welfare"}, {"id": "bc54ef95-8c64-4220-a293-328386ad144b", "type": "concept", "title": "Peer, family, caregiver, and recovery groups"}, {"id": "393b0352-734c-4d04-bdae-5e6d9de852d9", "type": "concept", "title": "Community consultation and culturally grounded practices"}], "description": "Methods must fit developmental level, culture, access needs, mandate, risk, and community knowledge."}]}, {"id": "38b3ee38-94a4-4275-b46c-c5e77cf3b532", "type": "topic", "title": "Task Groups, Teams, Coalitions, and Community-Action Groups", "description": "Extends group-work competence beyond treatment to committees, interdisciplinary teams, organizational change, advocacy, and collective action.", "children": [{"id": "daba2cfb-6fb1-4c88-a7fc-ee907e819031", "type": "subtopic", "title": "Task-group structure", "children": [{"id": "6ed467df-88bf-4cca-a067-577508efe055", "type": "concept", "title": "Charters, agendas, roles, and timelines"}, {"id": "f0bf5567-4646-4f0a-8324-4ca1b6ab793c", "type": "concept", "title": "Information flow and meeting design"}, {"id": "dc112049-9707-45bb-89b5-d6a46ee80564", "type": "concept", "title": "Consensus, voting, delegation, and accountability"}, {"id": "41341e5f-8446-4cdf-b8e5-b382f1ba3bd0", "type": "concept", "title": "Minutes, decisions, action registers, and follow-up"}], "description": "Task groups require disciplined attention to purpose, membership, authority, decision rights, and deliverables."}, {"id": "aaa9a5b6-e267-44ba-b7d0-fdd62a18d9c4", "type": "subtopic", "title": "Teams and interprofessional collaboration", "children": [{"id": "66695de2-5cfb-4b9b-8b34-51cf5c8ff585", "type": "concept", "title": "Team development and psychological safety"}, {"id": "a5ed4ddb-fb54-42a3-a0e7-6f406fa66fbd", "type": "concept", "title": "Role clarity and scope"}, {"id": "253bee97-8669-4e95-be43-76818f9223e5", "type": "concept", "title": "Conflict across disciplines"}, {"id": "0d1072c7-e3f7-446b-b0db-2a7ca4be5de7", "type": "concept", "title": "Case conferencing and shared care planning"}], "description": "Social workers often facilitate groups whose members hold different expertise, status, and institutional obligations."}, {"id": "6d4a63bb-1661-4479-8218-2b9ddf736fb2", "type": "subtopic", "title": "Coalitions and collective action", "children": [{"id": "154c7876-4825-4f36-885c-6971f4200e44", "type": "concept", "title": "Stakeholder and power mapping"}, {"id": "e263935b-2766-4118-836d-21f3284a1e30", "type": "concept", "title": "Participatory priority setting"}, {"id": "7b8ff667-48ed-4bb4-a8eb-8030140b31e0", "type": "concept", "title": "Coalition governance and shared leadership"}, {"id": "d31a719c-cc95-4bcb-a211-5ce29a321b73", "type": "concept", "title": "Advocacy strategy, public narrative, and sustainability"}], "description": "Community groups can build power, coordinate resources, and pursue structural change."}]}, {"id": "609701fb-1ade-416a-9d03-fd3a929e7bc9", "type": "topic", "title": "Documentation, Measurement, and Practice Evaluation", "description": "Develops ethical records and feasible evaluation plans that connect group purpose, process, participation, outcomes, equity, and continuous improvement.", "children": [{"id": "2e89c114-55b4-40e5-abe2-cf3a6d2ec33f", "type": "subtopic", "title": "Ethical group documentation", "children": [{"id": "a57c5726-dfe0-40e5-9b59-29c372c7da5b", "type": "concept", "title": "Attendance, purpose, interventions, participation, and response"}, {"id": "58d47d62-11cc-457e-a2ea-0da38969ca3d", "type": "concept", "title": "Individual versus group-level notes"}, {"id": "8f311449-bce5-4d58-9431-6d504f9d7d6d", "type": "concept", "title": "Objective, respectful, and behaviorally specific language"}, {"id": "47f17d92-34b9-494a-be9e-551e8dc1af67", "type": "concept", "title": "Minimum necessary information and secure records"}], "description": "Records should support continuity and accountability without unnecessarily exposing member disclosures."}, {"id": "87aeb3ae-39b8-46ce-ab42-077e218b7974", "type": "subtopic", "title": "Process and outcome measurement", "children": [{"id": "ff991a25-07d1-4170-a6c0-f72ac66e8da8", "type": "concept", "title": "Fidelity, dosage, attendance, retention, and participation"}, {"id": "ca8115e3-aeac-4c1f-a2d3-36a21a85f1c2", "type": "concept", "title": "Goal attainment and standardized measures"}, {"id": "aa817f10-5214-45a5-b3c2-db7ace54977b", "type": "concept", "title": "Member-defined outcomes and qualitative feedback"}, {"id": "ec979220-b64e-476e-b3fe-858602aacfa0", "type": "concept", "title": "Pre/post, repeated, and follow-up designs"}], "description": "Evaluation asks both whether the group was delivered well and whether meaningful change occurred."}, {"id": "ffcfcbd4-10bb-4919-8352-91214a31a0c0", "type": "subtopic", "title": "Interpretation and improvement", "children": [{"id": "6b7a10bd-3863-4cdd-b60c-24e200de52da", "type": "concept", "title": "Missing data, attrition, response bias, and small samples"}, {"id": "58bd5a9f-f780-4833-93de-da0c612abc59", "type": "concept", "title": "Disaggregated outcomes and equity"}, {"id": "2bd3b18f-694d-4dc8-af53-d9f0bb9bef19", "type": "concept", "title": "Clinical/practical versus statistical significance"}, {"id": "ec75218e-9d51-4e4d-9eed-34404370975a", "type": "concept", "title": "Feedback loops, adaptation, and dissemination"}], "description": "Data become useful when limitations, inequities, and unintended effects are examined with members and stakeholders."}]}, {"id": "ee7adc8f-a642-4599-a41a-6c078b53232d", "type": "topic", "title": "Online and Hybrid Group Practice", "description": "Adapts group design and facilitation for digital settings while addressing access, privacy, platform competence, engagement, crisis response, and cross-jurisdiction concerns.", "children": [{"id": "9e842c7b-5df2-4492-ab27-4c9927d0b91e", "type": "subtopic", "title": "Digital group design", "children": [{"id": "9ebe36c1-5f92-48c8-9200-5cd8c850f493", "type": "concept", "title": "Platform features and facilitator competence"}, {"id": "2d730b9d-72d2-4920-9240-286fa432a497", "type": "concept", "title": "Session length, pacing, breaks, and interaction"}, {"id": "10fee4ac-cee6-4075-832c-e8dc8e7a5558", "type": "concept", "title": "Digital materials and accessible formats"}, {"id": "1553af25-9561-42b1-b6b7-169c38d2d1b6", "type": "concept", "title": "Hybrid participation equity"}], "description": "Online practice requires intentional redesign rather than a simple transfer of in-person activities to video."}, {"id": "8a862157-4299-4d9c-a73e-49fb9ff7dcee", "type": "subtopic", "title": "Privacy, consent, and access", "children": [{"id": "987e9110-2e37-4633-a949-310cd373c061", "type": "concept", "title": "Private space, headphones, identities, and location checks"}, {"id": "25a4e9ff-3508-4ad0-b700-8e412d95b418", "type": "concept", "title": "Encryption, recording, chat, storage, and vendor policies"}, {"id": "b84e7a97-79da-4ada-87b8-b3425e631f08", "type": "concept", "title": "Digital divide, devices, bandwidth, and accommodations"}, {"id": "6e51f3c9-034f-48a4-ab28-69c9c81c92af", "type": "concept", "title": "Backup channels and technology failure plans"}], "description": "Technology changes who can participate, what can be overheard or recorded, and how data move."}, {"id": "7a876026-54c0-46d9-a454-03d8319417ce", "type": "subtopic", "title": "Engagement and crisis protocols", "children": [{"id": "c0d69ed6-66cf-4613-a699-2cae7a553402", "type": "concept", "title": "Camera choice and nonvisual participation"}, {"id": "8ad2e106-2eb1-4352-9f40-7f8e19f0c0b0", "type": "concept", "title": "Breakout rooms, chat, polls, and collaborative tools"}, {"id": "662bffd2-75c7-433e-8102-5c6139bcdeec", "type": "concept", "title": "Cross-jurisdiction and emergency contacts"}, {"id": "0762063c-d317-40f7-a8a6-cf249ac771fa", "type": "concept", "title": "Disconnection, acute risk, and welfare-check protocols"}], "description": "Facilitators need ways to read process, build connection, and respond when members are physically distant."}]}, {"id": "5eec1fb4-3d58-4cd7-9b45-277bec014e8f", "type": "topic", "title": "Ending, Transition, Follow-Up, and Integrative Practice", "description": "Treats termination as a planned phase for consolidating learning, acknowledging loss, evaluating outcomes, supporting next steps, and integrating professional competence.", "children": [{"id": "57f35d08-8f55-4625-8331-814862c7c2a4", "type": "subtopic", "title": "Planned endings", "children": [{"id": "9e3d91c6-85ee-4903-bd12-aaf8c2ccad52", "type": "concept", "title": "Advance preparation and timeline"}, {"id": "ba34f758-3a4e-46f3-9843-d3bf34ba900d", "type": "concept", "title": "Review of goals, learning, and mutual aid"}, {"id": "15274cce-67fc-4338-9716-bfda1b3d40e8", "type": "concept", "title": "Expression of feelings and unfinished business"}, {"id": "4ba607db-ab90-49bf-85b5-5c584389eeb3", "type": "concept", "title": "Rituals, celebration, and culturally responsive closure"}], "description": "Termination deserves the same intentionality as beginnings because it activates meaning, loss, achievement, and future risk."}, {"id": "9b715a25-37f3-49e2-94ba-9384c58aa2eb", "type": "subtopic", "title": "Transition and continuity", "children": [{"id": "0b0629d5-5482-465f-9cfd-cba2dd36a431", "type": "concept", "title": "Relapse/setback planning and skill generalization"}, {"id": "dc3bff17-e307-4595-bc81-365984379872", "type": "concept", "title": "Referrals, peer supports, and community resources"}, {"id": "a97be931-7ca9-409d-bf22-d3741a5ad4a8", "type": "concept", "title": "Follow-up contacts and booster sessions"}, {"id": "d59fbaf0-c636-4925-bdf7-d7331eabe86d", "type": "concept", "title": "Unexpected endings, dropout, and facilitator departure"}], "description": "Members need realistic next steps that support transfer beyond the group."}, {"id": "8374d450-57bc-4f84-9b88-4fc270f8127b", "type": "subtopic", "title": "Integrative practice demonstration", "children": [{"id": "67c50533-296e-4760-adc3-cf86076ebe83", "type": "concept", "title": "Session plan linked to purpose and phase"}, {"id": "ca1f1de4-a786-4398-8bff-7cdea0903c5f", "type": "concept", "title": "Live or recorded simulation with no compelled personal disclosure"}, {"id": "3f778afb-6e4f-4d87-a410-f62656700605", "type": "concept", "title": "Annotated process analysis and ethical rationale"}, {"id": "157cae69-d963-4fd5-b442-efbf7e9c14f4", "type": "concept", "title": "Peer/supervisor feedback and deliberate-practice goals"}], "description": "A capstone makes competence observable and turns feedback into a development plan."}]}], "dbBacked": true}$swgrjson$::jsonb,
